import{_ as o,o as a,c as t,a2 as s}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"Building Open Cube OS","description":"","frontmatter":{},"headers":[],"relativePath":"root/BUILDING.md","filePath":"root/BUILDING.md"}'),i={name:"root/BUILDING.md"};function n(d,e,c,l,r,p){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="building-open-cube-os" tabindex="-1">Building Open Cube OS <a class="header-anchor" href="#building-open-cube-os" aria-label="Permalink to &quot;Building Open Cube OS&quot;">​</a></h1><p>Everything below is executable reality: the file names, targets and checks come from <code>Makefile</code>, <code>tools/build.sh</code>, <code>tools/build.ps1</code> and the CI pipeline (<code>.github/workflows/build.yml</code>).</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Target</th><th>Produces</th></tr></thead><tbody><tr><td><code>make kernel</code></td><td><code>build/opencube.elf</code> - the kernel ELF (0 warnings, <code>-Wall -Wextra -Werror</code>)</td></tr><tr><td><code>make iso</code></td><td><code>build/opencube.iso</code> - hybrid BIOS+UEFI bootable ISO</td></tr><tr><td><code>make src-zip</code></td><td><code>dist/OpenCubeOS-&lt;version&gt;-src.zip</code> - deterministic source zip</td></tr><tr><td><code>make ota</code></td><td><code>dist/OpenCubeOS-&lt;version&gt;-update.tar.gz</code> - OTA update package</td></tr><tr><td><code>make all</code></td><td>kernel + ISO + SRC zip + OTA</td></tr><tr><td><code>make test</code></td><td>host-side unit tests (<code>tools/run_host_tests.py</code>)</td></tr><tr><td><code>make reproducible-check</code></td><td>two clean builds, byte-identical ELF</td></tr><tr><td><code>make api-docs</code></td><td>real-tree documentation data (<code>docs/data/*.json</code>)</td></tr></tbody></table><p>One-command entries: <code>tools/build.sh</code> (Linux; same target names plus dependency detection and <code>--install</code>), <code>build.ps1</code> (Windows via WSL2 / MSYS2).</p><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h2><h3 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h3><p><code>gcc, ld (binutils), nasm, grub-mkimage (grub-common), xorriso, mtools (mformat/mcopy), python3, zip</code>.</p><p><code>tools/build.sh</code> checks all of them and prints the exact Debian package names for anything missing; <code>./build.sh --install</code> apt-installs them when you are root. Building the ISO additionally needs the GRUB module trees (<code>grub-pc-bin</code> for <code>i386-pc</code>, <code>grub-efi-amd64-bin</code> for <code>x86_64-efi</code>) and <code>unicode.pf2</code> from <code>grub-common</code>.</p><p>For QEMU testing: <code>qemu-system-x86</code>, <code>seabios</code>, <code>ipxe-qemu</code>, <code>ovmf</code> (UEFI). On a Debian/Ubuntu host:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt-get install gcc nasm xorriso mtools \\</span></span>
<span class="line"><span>     grub-common grub-pc-bin grub-efi-amd64-bin zip python3 \\</span></span>
<span class="line"><span>     qemu-system-x86 ovmf</span></span></code></pre></div><h3 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/cubestudio-dev/OpenCubeOS.git</span></span>
<span class="line"><span>cd OpenCubeOS</span></span>
<span class="line"><span>./build.sh            # = make all</span></span>
<span class="line"><span># or step by step:</span></span>
<span class="line"><span>make -j&quot;$(nproc)&quot; kernel</span></span>
<span class="line"><span>make iso</span></span></code></pre></div><p>The version banner comes from the <code>2.0.0</code> literal in the Makefile (override with <code>make OC_RELEASE_VERSION=1.0.1-test1</code>). The build number is the commit count plus the +21 alignment offset (see the Makefile note) so the public sequence stays above the published 274.</p><h3 id="boot-and-test" tabindex="-1">Boot and test <a class="header-anchor" href="#boot-and-test" aria-label="Permalink to &quot;Boot and test&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make run-bios     # QEMU legacy BIOS boot</span></span>
<span class="line"><span>make run-uefi     # QEMU UEFI boot (OVMF)</span></span>
<span class="line"><span>make test         # host unit tests</span></span>
<span class="line"><span>make shot-bios    # boot screenshot capture</span></span></code></pre></div><p>Networking on: add <code>-netdev user,id=n1 -device e1000,netdev=n1</code> (the <code>run-bios</code> target already does) then <code>dhcp</code> inside the guest.</p><h3 id="reproducible-verification" tabindex="-1">Reproducible verification <a class="header-anchor" href="#reproducible-verification" aria-label="Permalink to &quot;Reproducible verification&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make reproducible-check</span></span>
<span class="line"><span># reproducible-check: PASS - ELF byte-identical across two clean builds</span></span></code></pre></div><p>Determinism sources (all verified in-tree): no <code>__DATE__</code>/<code>__TIME__</code>/ <code>__TIMESTAMP__</code> macros, stable <code>grub-mkimage</code> output for identical inputs, fixed link order, <code>strip --strip-debug</code> removing path-bearing sections. The SRC zip is deterministic by construction (<code>git archive</code>: tree order, commit mtimes, index permissions). The OTA package contains the build day in UTC - it reproduces byte-identically within a day, which is the documented guarantee.</p><p><code>SOURCE_DATE_EPOCH</code> is honoured when exported and forwarded to the packaging sub-tools.</p><h3 id="cross-compilation-arm64-risc-v-bring-up-shells" tabindex="-1">Cross-compilation (ARM64 / RISC-V bring-up shells) <a class="header-anchor" href="#cross-compilation-arm64-risc-v-bring-up-shells" aria-label="Permalink to &quot;Cross-compilation (ARM64 / RISC-V bring-up shells)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make ARCH=arm64    # build/arch/arm64/opencube-arm64.elf (PL011 UART shell)</span></span>
<span class="line"><span>make ARCH=riscv    # build/arch/riscv/opencube-riscv.elf (NS16550A UART shell)</span></span></code></pre></div><p>These are real bare-metal bring-up shells: PL011 / NS16550A UARTs with true divisor programming, the ARM generic timer / RISC-V CLINT mtime counter, and a 1-second heartbeat - banners and incrementing heartbeats verified live in QEMU (<code>qemu-system-aarch64 -M virt</code>, <code>qemu-system-riscv64 -M virt</code>). The full kernel feature set is x86_64 only.</p><p>Cross toolchain packages (Debian): <code>gcc-aarch64-linux-gnu binutils-aarch64-linux-gnu</code>, <code>gcc-riscv64-linux-gnu binutils-riscv64-linux-gnu</code>, <code>qemu-system-arm</code>, <code>qemu-system-misc</code>.</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><p><code>build.ps1</code> (PowerShell) forwards the build to the same Makefile from the best available environment, in this order:</p><ol><li><strong>WSL2</strong> (recommended) - a Debian/Ubuntu WSL distribution with the Linux dependencies above. The script translates Windows paths with <code>wslpath</code> and runs <code>make</code> inside WSL.</li><li><strong>MSYS2</strong> - a locally installed MSYS2 with <code>mingw-w64</code> gcc, nasm, mtools, xorriso, grub packages on its PATH.</li><li>Otherwise the script prints the exact packages to install and exits non-zero.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>powershell -ExecutionPolicy Bypass -File build.ps1            # full pipeline</span></span>
<span class="line"><span>powershell -ExecutionPolicy Bypass -File build.ps1 iso        # kernel + ISO</span></span></code></pre></div><h2 id="multi-configuration-builds" tabindex="-1">Multi-configuration builds <a class="header-anchor" href="#multi-configuration-builds" aria-label="Permalink to &quot;Multi-configuration builds&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make defconfig          # write .config (all options on)</span></span>
<span class="line"><span>make menuconfig         # interactive configurator (tools/oc_menuconfig.sh)</span></span>
<span class="line"><span>make CONFIG_TUI=n       # one-shot override</span></span></code></pre></div><p>Options: <code>CONFIG_TUI</code>, <code>CONFIG_CHINESE</code>, <code>CONFIG_NVME</code>, <code>CONFIG_AHCI</code>, <code>CONFIG_VIRTIO_BLK</code>. <code>CONFIG_CHINESE=n</code> forces <code>CONFIG_TUI=n</code>. A <code>CONFIG_TUI=n CONFIG_CHINESE=n</code> build drops the 9 TUI commands from the <code>oc&gt;</code> surface (99 -&gt; 90) and turns the 8 chinese-locale SVC ops into clean -1 errors (the command bodies live in the filtered trees; op numbers stay stable); the full configuration boots 99 L0 commands with 251 command homes in total (2.1.0-verified live: banner + <code>help -a</code> on the off-path ISO). The off-path is real code, not deleted code - the configurator&#39;s generated header maps disabled features to no-op equivalents, and the L1SVC dispatch guards the locale ops (2.1.0: the v2.0.0 tree failed to link the off-path image - fixed).</p><h2 id="build-cache" tabindex="-1">Build cache <a class="header-anchor" href="#build-cache" aria-label="Permalink to &quot;Build cache&quot;">​</a></h2><p>The compile cache (<code>tools/oc_cc.sh</code>) is content-addressed: the key is the compiler identity + full flags + the content hash of the source and of every header dependency. Measured on the release tree: cold 46.6 s -&gt; warm 14.4 s (186/186 objects hit, 3.2x), warm output byte-identical to cold. Cache control: <code>make cache-stats</code>, <code>make cache-clear</code>.</p><h2 id="scriptable-build-api" tabindex="-1">Scriptable build API <a class="header-anchor" href="#scriptable-build-api" aria-label="Permalink to &quot;Scriptable build API&quot;">​</a></h2><p><code>tools/build.sh</code> exposes its pipeline as sourceable functions (<code>build_all</code>, <code>build_iso</code>, <code>config_load</code>, <code>cache_lookup</code>, <code>cross_compile</code>, ...) with <code>tools/build.sh api-selftest</code> verifying the 8 spec&#39;d interfaces. Release scripts and CI compose these instead of parsing make output.</p><h2 id="ci" tabindex="-1">CI <a class="header-anchor" href="#ci" aria-label="Permalink to &quot;CI&quot;">​</a></h2><p><code>.github/workflows/build.yml</code> runs on every push and PR to <code>main</code>: checkout (full history + tags so <code>git describe</code> feeds the version banner), dependency install, kernel (<code>-Wall -Wextra -Werror</code>), hybrid ISO, deterministic SRC zip, OTA package, host test suite, artifact digests + upload, and the reproducibility gate. QEMU boots and E2E suites are release-host activities (they need the persisted /etc volume fixture) - see <code>docs/release/</code> for the full release gate.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong><code>grub-mkimage: cannot open ... unicode.pf2</code></strong> - the font lives in <code>grub-common</code>; if your distro splits it, point <code>OC_TOOLS</code> at a tree containing <code>usr/share/grub/unicode.pf2</code>.</li><li><strong><code>src-zip: not a git checkout</code></strong> - the deterministic source zip needs git metadata; build from a clone, or use <code>make dist</code> for a plain tar-based fallback.</li><li><strong>QEMU cannot find firmware</strong> - <code>OC_TOOLS</code> relocates the whole toolchain; QEMU&#39;s datadir is probed under <code>$OC_TOOLS/usr/share/qemu</code> and <code>$OC_TOOLS/share/qemu</code>.</li><li><strong><code>setc</code> / <code>packed-member</code> build errors on very new GCC/binutils</strong> - fixed in the tree; update past the CI-green commit <code>fc4e5a5</code>.</li></ul>`,40)])])}const b=o(i,[["render",n]]);export{u as __pageData,b as default};
